var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e.DebugAktiv').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - Cupra.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------->>> Verriegelung
on({ id: [].concat(['0_userdata.0.go-e.AUTO']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.go-e.AUTO').val == true) {
    setState('0_userdata.0.go-e.NOT' /* NOT */, false);
    setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, false);
    setState('0_userdata.0.go-e.Timeout' /* Timeout */, 0);
  }
});
on({ id: [].concat(['0_userdata.0.go-e.NOT']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.go-e.NOT').val == true) {
    setState('0_userdata.0.go-e.AUTO' /* AUTO */, false);
    setState('0_userdata.0.go-e.LADUNG' /* LADUNG */, false);
    setState('0_userdata.0.go-e.Timeout' /* Timeout */, 0);
  }
});
on({ id: [].concat(['0_userdata.0.go-e.1P']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.go-e.1P').val == true) {
    setState('0_userdata.0.go-e.3P' /* 3P */, false);
  }
});
on({ id: [].concat(['0_userdata.0.go-e.3P']), change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  if (getState('0_userdata.0.go-e.3P').val == true) {
    setState('0_userdata.0.go-e.1P' /* 1P */, false);
  }
});

// DC Spannungen angleichen
on({ id: 'mqtt.1.ioBroker.ESS_MaxChargeVoltage' /* ioBroker/ESS_MaxChargeVoltage */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  setState('mqtt.2.ioBroker.BAT_MaxChargeVoltage' /* ioBroker/BAT_MaxChargeVoltage */, getState('mqtt.1.ioBroker.ESS_MaxChargeVoltage').val);
});
on({ id: 'mqtt.2.ioBroker.BAT_MaxChargeVoltage' /* ioBroker/BAT_MaxChargeVoltage */, change: 'ne' }, async (obj) => {
  let value = obj.state.val;
  let oldValue = obj.oldState.val;
  setState('mqtt.1.ioBroker.ESS_MaxChargeVoltage' /* ioBroker/ESS_MaxChargeVoltage */, getState('mqtt.2.ioBroker.BAT_MaxChargeVoltage').val);
});


